function offAt(tz,ms){var f=new Intl.DateTimeFormat('fr-FR',{timeZone:tz,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}),p={};f.formatToParts(new Date(ms)).forEach(function(x){p[x.type]=x.value;});return Math.round((Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)-Math.floor(ms/1000)*1000)/60000);}
