function clock(ms,tz,h12){var d=new Date(ms+offAt(tz,ms)*60000),h=d.getUTCHours(),m=d.getUTCMinutes();if(h12)return ((h%12)||12)+':'+p2(m)+' '+(h>=12?'PM':'AM');return p2(h)+':'+p2(m);}
function dayKey(ms,tz){return Math.floor((ms+offAt(tz,ms)*60000)/86400000);}
