  C.text('resultValue',(h12?clock(ms,'UTC',true):p2(d.getUTCHours())+':'+p2(d.getUTCMinutes()))+' UTC');C.text('tag',dstr);
  C.text('interp',v.replace('T',' ')+' in '+$('zn').options[$('zn').selectedIndex].text+' ('+offTxt(off)+(abbr(tz,ms)?', '+abbr(tz,ms):'')+').');
